import express from 'express';
import { DatabaseSync } from 'node:sqlite';
import { cashierSessionAuth } from './auth.js';

const app = express();
const db = new DatabaseSync('/var/pos/local_store.db');

app.get('/api/pos/transactions/:txnId/receipt', cashierSessionAuth, (req, res) => {
  const { txnId } = req.params;

  // Restrict receipt lookup to the store assigned to the authenticated cashier session
  const stmt = db.prepare(`
    SELECT txn_id, store_id, terminal_id, customer_name, customer_phone, total_cents, masked_pan
    FROM offline_receipts
    WHERE txn_id = ? AND store_id = ?
  `);

  const receipt = stmt.get(txnId, req.cashier.storeId);
  if (!receipt) {
    return res.status(404).json({ error: 'Transaction receipt not found or access denied' });
  }

  res.json({ receipt });
});

export default app;
